export function isCurrentMember(member: Member | null): member is Member {
  return (
    member !== null && member.archivedAt === null && member.status === "active"
  );
}

/** The (org, user) membership, but only while it is current. */
export async function findCurrentMember(
  orgId: OrgId,
  userId: UserId,
): Promise<Member | null> {
  const member = await findMember(orgId, userId);
  return isCurrentMember(member) ? member : null;
}

/** The subset of `userIds` that are current members of `orgId`. */
export async function filterCurrentMemberUserIds(
  orgId: OrgId,
  userIds: readonly UserId[],
): Promise<readonly UserId[]> {
  const unique = [...new Set(userIds)];
  if (unique.length === 0) return [];

  const rows = getDb()
    .select({ userId: members.userId })
    .from(members)
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        inArray(members.userId, unique),
        eq(members.status, "active"),
        liveMemberPredicate(),
      ),
    )
    .all();

  const current = new Set<string>(rows.map((row) => row.userId));
  return unique.filter((userId) => current.has(userId));
}

